<?php
declare(strict_types=1);
require_once __DIR__ . '/lib.php';
boot_session();
if (!is_logged_in()) { header('Location: index.php'); exit; }
header('Cache-Control: no-store, private');
$providers = array_values(array_filter(catalog()['providers'] ?? [], static fn($p): bool => is_array($p) && parse_url((string)($p['baseUrl'] ?? ''), PHP_URL_HOST) === 'api.yunhui.me'));
$providerChoices = array_map(static fn($p): array => ['key' => $p['key'], 'name' => $p['name'], 'format' => $p['format']], $providers);
?>
<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>模型同步 · 云汇AI</title><style>
:root{font-family:'Microsoft YaHei','PingFang SC',system-ui,sans-serif;color:#26334a;background:#f5f7fb;font-size:14px}*{box-sizing:border-box}body{margin:0}main{max-width:1180px;margin:auto;padding:36px 26px}a{color:#5265db;text-decoration:none}h1{font-size:28px;margin:12px 0}h2{font-size:18px}p{color:#758097;line-height:1.8}header,.row{display:flex;align-items:center;gap:12px;flex-wrap:wrap}header{justify-content:space-between}.card{background:#fff;border:1px solid #e3e8f0;border-radius:16px;padding:22px;margin:20px 0}.status{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.status b{display:block;margin-top:9px;font-size:20px}button,input,select{font:inherit;border-radius:9px;border:1px solid #dce2ed;padding:10px 13px;background:#fff;color:#394862}button{cursor:pointer}button.primary{background:#5d6ee8;color:white;border-color:#5d6ee8}button:disabled{opacity:.5;cursor:wait}input[type=search]{min-width:220px;flex:1}input[type=checkbox]{accent-color:#5d6ee8;width:16px;height:16px}.scroll{overflow:auto;max-height:570px}table{border-collapse:collapse;width:100%;text-align:left;font-size:13px}th,td{border-bottom:1px solid #eef1f6;padding:12px 8px}th{color:#7c879b;background:#fafbfe;position:sticky;top:0}code{font-family:Consolas,monospace}#message{padding:13px 17px;background:#eaf0ff;border-radius:11px;display:none;margin-top:18px}.muted{color:#8993a5}.small{font-size:12px}@media(max-width:650px){main{padding:20px 14px}.card{padding:15px}.status{grid-template-columns:1fr}.row>*{max-width:100%}}
</style></head><body><main><header><div><a href="index.php">← 返回云端管理</a><h1>云汇模型自动同步</h1><p>每天读取分组候选目录，精选推荐由你决定。</p></div><button id="sync" class="primary">立即同步模型</button></header><div id="message" role="status"></div>
<div class="card status"><div>最近成功同步<b id="last">尚未同步</b></div><div>完整候选模型<b id="count">—</b></div><div>最近运行结果<b id="result">—</b></div></div>
<section class="card"><h2>完整候选目录</h2><p>这里包含上游分组公布的模型 ID。分组候选不保证每个账户当前可调用，客户端会再用会员 API Key 读取实际列表。同步不改动其他厂商、不覆盖手工定价，也不会恢复已删除或下架的推荐。</p><div class="row"><input id="search" type="search" placeholder="搜索模型 ID" aria-label="搜索模型"><select id="platform" aria-label="平台"><option value="">全部平台</option></select><select id="provider" aria-label="加入的供应商"></select><button id="add">将所选加入精选</button></div><p id="shown" class="small muted"></p><div class="scroll"><table><thead><tr><th>选择</th><th>模型 ID</th><th>平台</th><th>可选分组</th></tr></thead><tbody id="models"></tbody></table></div></section>
<section class="card"><h2>同步运行记录</h2><p id="audit" class="small"></p></section><p class="small">同步任务只读上游管理接口，不测试模型推理、不创建账户、不消耗模型额度。管理密钥始终留在服务器。</p></main>
<script>
const csrf = <?= json_encode(csrf_token(), JSON_HEX_TAG | JSON_HEX_AMP) ?>;
const providers = <?= json_encode($providerChoices, JSON_HEX_TAG | JSON_HEX_AMP | JSON_HEX_APOS | JSON_HEX_QUOT) ?>;
let state={catalog:{models:[],groups:[]},status:{}};const selected=new Set();let busy=false;
const byId=id=>document.getElementById(id);
function message(text){byId('message').textContent=text;byId('message').style.display='block'}
async function api(action,payload){const r=await fetch('api.php?a='+encodeURIComponent(action),{method:payload?'POST':'GET',headers:{'Content-Type':'application/json','X-CSRF':csrf},...(payload?{body:JSON.stringify(payload)}:{})});const j=await r.json();if(!r.ok||j.error)throw new Error(j.error||'操作失败');return j}
function cell(row,text){const td=document.createElement('td');td.textContent=text;row.appendChild(td);return td}
function render(){const status=state.status||{};byId('last').textContent=status.lastSuccessAt?new Date(status.lastSuccessAt).toLocaleString():'尚未同步';byId('count').textContent=(state.catalog.models||[]).length;byId('result').textContent=status.lastResult==='success'?'同步成功':status.lastResult==='failed'?'失败，保留上次结果':'等待首次运行';const keyword=byId('search').value.trim().toLowerCase();const platform=byId('platform').value;const all=(state.catalog.models||[]).filter(m=>(!platform||m.platform===platform)&&m.id.toLowerCase().includes(keyword));byId('shown').textContent='符合条件 '+all.length+' 个，当前显示前 300 个，已选 '+selected.size+' 个。';const body=byId('models');body.replaceChildren();for(const m of all.slice(0,300)){const row=document.createElement('tr');const box=document.createElement('input');box.type='checkbox';box.checked=selected.has(m.platform+':'+m.id);box.setAttribute('aria-label','选择 '+m.id);box.onchange=()=>{if(box.checked)selected.add(m.platform+':'+m.id);else selected.delete(m.platform+':'+m.id);render()};cell(row,'').appendChild(box);cell(row,m.id);cell(row,m.platform);cell(row,(m.groups||[]).join('、'));body.appendChild(row)}byId('audit').textContent=(status.audit||[]).slice(0,10).map(a=>new Date(a.at).toLocaleString()+' · '+(a.result==='success'?'同步成功':a.result==='selection'?'精选已更新':'同步失败')+(a.error?' · '+a.error:'')).join('\n');byId('audit').style.whiteSpace='pre-line'}
async function load(){state=await api('catalog.sync.status');const previous=byId('platform').value;byId('platform').replaceChildren(new Option('全部平台',''));for(const p of [...new Set((state.catalog.models||[]).map(m=>m.platform))])byId('platform').add(new Option(p,p));byId('platform').value=previous;render()}
async function run(fn){if(busy)return;busy=true;byId('sync').disabled=byId('add').disabled=true;try{await fn()}catch(e){message(e.message)}finally{busy=false;byId('sync').disabled=byId('add').disabled=false}}
byId('sync').onclick=()=>run(async()=>{message('正在从上游读取模型目录…');const r=await api('catalog.sync.run',{});message(r.message);await load()});
byId('add').onclick=()=>run(async()=>{const provider=providers.find(p=>p.key===byId('provider').value);if(!provider)throw new Error('请先在供应商目录建立云汇供应商');const platforms={'openai-responses':['openai'],'openai-chat':['openai','deepseek','grok'],'anthropic':['anthropic'],'gemini':['gemini']}[provider.format]||[];const models=(state.catalog.models||[]).filter(m=>selected.has(m.platform+':'+m.id));if(models.some(m=>!platforms.includes(m.platform)))throw new Error('选择中包含与目标供应商协议不兼容的平台，请按平台筛选后添加');const r=await api('catalog.sync.select',{providerKey:provider.key,ids:[...new Set(models.map(m=>m.id))]});selected.clear();if(r.warning){message('已向精选加入 '+r.added+' 个模型。'+r.warning);render();return}message('已向精选加入 '+r.added+' 个模型，原有手工字段已保留。');await load()});
for(const p of providers)byId('provider').add(new Option(p.name+' · '+p.format,p.key));byId('search').oninput=render;byId('platform').onchange=render;load().catch(e=>message(e.message));
</script><footer style="text-align:center;padding:20px;color:#7b8595;font-size:12px"><a href="https://github.com/yunhui201/yunhui.me/tree/main" target="_blank" rel="noopener noreferrer">yunhui.me · 项目源码</a> · <a href="https://github.com/yunhui201/yunhui.me/blob/main/LICENSE" target="_blank" rel="noopener noreferrer">AGPL-3.0 许可</a></footer>
</body></html>
